import base64
encoded = b''
decoded = base64.b64decode(encoded).decode('utf-8')
import re
with open('backend/app/api/routes/telegram.py', 'r', encoding='utf-8') as f:
    content = f.read()
pattern = re.compile(r'async def _handle_message.*?# ─── Endpoints', re.DOTALL)
new_content = pattern.sub(decoded + '\n\n# ─── Endpoints', content)
with open('backend/app/api/routes/telegram.py', 'w', encoding='utf-8') as f:
    f.write(new_content)
